SELECT 'risk' src, ri_id id, process_step, parameter_txt, cqa_impacted, failure_mode, rpn::text, current_controls, assurance_approach FROM pd.val_risk_item WHERE cqa_impacted ILIKE '%CAR%' OR parameter_txt ILIKE '%CAR%' OR failure_mode ILIKE '%CAR%' OR effect ILIKE '%CAR%' OR cause ILIKE '%CAR%'
UNION ALL SELECT 'spec', item_id, req_category, item_text, source, doc_no, NULL, NULL, NULL FROM pd.val_spec_item WHERE item_text ILIKE '%CAR%'
UNION ALL SELECT 'ppq', protocol_id, crit_class, attribute_txt, lo::text, hi::text, NULL, NULL, NULL FROM pd.val_ppq_criterion WHERE attribute_txt ILIKE '%CAR%';
